package org.example.controller;

import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;
import org.example.model.Produit;
import org.example.service.ProduitService;

import java.io.IOException;

public class AccueilController {

    @FXML private TextField searchField;
    @FXML private Button searchButton;
    @FXML private Button profileButton;
    @FXML private VBox profileDropdown;

    private ProduitService produitService = new ProduitService();

    @FXML
    public void initialize() {
        // Add sample products
        addSampleProducts();
        loadProducts();
    }

    private void addSampleProducts() {
        produitService.add(new Produit(0, "Paracétamol", "Antalgique et antipyrétique", 5.50, 100, "Analgésiques", true));
        produitService.add(new Produit(0, "Ibuprofène", "Anti-inflammatoire non stéroïdien", 4.20, 80, "Anti-inflammatoires", true));
        produitService.add(new Produit(0, "Aspirine", "Antalgique et antiagrégant", 3.80, 120, "Analgésiques", true));
        produitService.add(new Produit(0, "Vitamine C", "Supplément vitaminique", 8.90, 50, "Vitamines", true));
    }

    @FXML
    private void handleSearch() {
        String query = searchField.getText();
        if (!query.isEmpty()) {
            var results = produitService.search(query);
            displayProducts(results);
        } else {
            loadProducts();
        }
    }

    private void loadProducts() {
        var produits = produitService.getAll();
        displayProducts(produits);
    }

    private void displayProducts(java.util.List<Produit> produits) {
        profileDropdown.getChildren().clear();
        for (Produit p : produits) {
            VBox productCard = new VBox(10);
            productCard.setStyle("-fx-background-color: white; -fx-padding: 20; -fx-background-radius: 15; -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 10, 0, 0, 5); -fx-alignment: center-left;");
            productCard.getStyleClass().add("card");
            productCard.getStyleClass().add("card-hover");

            Label nameLabel = new Label(p.getNom());
            nameLabel.setStyle("-fx-font-weight: bold; -fx-font-size: 18px; -fx-text-fill: #1E1E1E;");

            Label descLabel = new Label(p.getDescription());
            descLabel.setStyle("-fx-text-fill: #6B7280; -fx-wrap-text: true;");

            Label priceLabel = new Label(p.getPrix() + " €");
            priceLabel.setStyle("-fx-font-weight: bold; -fx-font-size: 16px; -fx-text-fill: #145A44;");

            productCard.getChildren().addAll(nameLabel, descLabel, priceLabel);
            profileDropdown.getChildren().add(productCard);
        }
    }

    @FXML
    private void toggleProfileDropdown() {
        boolean isVisible = profileDropdown.isVisible();
        profileDropdown.setVisible(!isVisible);
        profileDropdown.setManaged(!isVisible);
    }

    @FXML
    private void goToDashboard() throws IOException {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Dashboard.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root, 1400, 900);
        scene.getStylesheets().add(getClass().getResource("/css/styles.css").toExternalForm());
        Stage stage = (Stage) profileButton.getScene().getWindow();
        stage.setScene(scene);
    }
}

