    -fx-translate-x: 60;
}

/* Dropdown Item */
.dropdown-item {
    -fx-background-color: transparent;
    -fx-text-fill: #1f6f5c;
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI", sans-serif;
    -fx-padding: 12 20;
    -fx-cursor: hand;
    -fx-background-radius: 0;
