/* ============================================
   MODERN ACCUEIL - CARDS SECTION
   ============================================ */

/* Main Content Area */
.main-content {
    -fx-background-color: transparent;
}

/* Cards Section */
.cards-section {
    -fx-padding: 40;
    -fx-spacing: 30;
}

/* Card Container */
.card {
    -fx-background-color: white;
    -fx-background-radius: 20;
    -fx-padding: 25;
    -fx-spacing: 15;
