/* ============================================
   League of Legends Style - Login Page
   ============================================ */

/* Root Background */
.lol-root {
    -fx-background-color: linear-gradient(to bottom right, #1F6F54, #2E8B57);
    -fx-min-width: 900;
    -fx-min-height: 550;
}

/* Floating Background Animation */
.floating-bg {
    -fx-background-color: transparent;
}

.floating-circle {
    -fx-background-color: rgba(255, 255, 255, 0.1);
    -fx-shape: "M50,0 C77.6,0 100,22.4 100,50 C100,77.6 77.6,100 50,100 C22.4,100 0,77.6 0,50 C0,22.4 22.4,0 50,0";
    -fx-min-width: 200;
    -fx-min-height: 200;
    -fx-pref-width: 250;
    -fx-pref-height: 250;
    -fx-opacity: 0;
}

/* Main Card Container */
.lol-card {
    -fx-background-color: white;
    -fx-background-radius: 20;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.4), 30, 0.5, 0, 10);
    -fx-min-width: 850;
    -fx-min-height: 500;
    -fx-max-width: 900;
    -fx-max-height: 550;
}

/* Card Content Container with Clip */
.card-content-container {
    -fx-min-width: 850;
    -fx-min-height: 500;
    -fx-clip-rects: 0 0 850 500;
}

/* Form Panels */
.form-panel-left {
    -fx-background-color: white;
    -fx-min-width: 428;
    -fx-min-height: 500;
    -fx-max-width: 428;
    -fx-max-height: 500;
    -fx-alignment: center;
    -fx-padding: 40;
    -fx-translate-x: 0;
}

.form-panel-right {
    -fx-background-color: white;
    -fx-min-width: 428;
    -fx-min-height: 500;
    -fx-max-width: 428;
    -fx-max-height: 500;
    -fx-alignment: center;
    -fx-padding: 40;
}

/* Sliding Panel - Green Overlay */
.sliding-panel {
    -fx-background-color: #1F6F54;
    -fx-min-width: 422;
    -fx-min-height: 500;
    -fx-alignment: center;
    -fx-padding: 40;
}

/* Titles */
.lol-title {
    -fx-font-size: 36;
    -fx-font-family: "Segoe UI Light", sans-serif;
    -fx-fill: #1a1a1a;
    -fx-font-weight: bold;
}

.lol-subtitle {
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI", sans-serif;
    -fx-fill: #888;
}

.panel-title {
    -fx-font-size: 32;
    -fx-font-family: "Segoe UI Light", sans-serif;
    -fx-fill: white;
    -fx-font-weight: bold;
}

.panel-subtitle {
    -fx-font-size: 13;
    -fx-font-family: "Segoe UI", sans-serif;
    -fx-fill: rgba(255,255,255,0.8);
}

/* Input Fields */
.lol-input {
    -fx-background-color: #f5f7fa;
    -fx-background-radius: 10;
    -fx-border-radius: 10;
    -fx-padding: 12 15 12 15;
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI", sans-serif;
    -fx-min-height: 42;
    -fx-min-width: 280;
    -fx-prompt-text-fill: #999;
}

.lol-input:focused {
    -fx-background-color: white;
    -fx-border-color: #1F6F54;
    -fx-border-width: 2;
    -fx-border-radius: 10;
}

/* Buttons */
.lol-button-primary {
    -fx-background-color: #1F6F54;
    -fx-background-radius: 20;
    -fx-text-fill: white;
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI Semibold", sans-serif;
    -fx-font-weight: bold;
    -fx-letter-spacing: 2;
    -fx-cursor: hand;
    -fx-min-height: 45;
}

.lol-button-primary:hover {
    -fx-background-color: #258562;
}

.lol-button-primary:pressed {
    -fx-background-color: #1a5c43;
    -fx-scale-x: 0.98;
    -fx-scale-y: 0.98;
}

.lol-button-panel {
    -fx-background-color: transparent;
    -fx-background-radius: 20;
    -fx-border-color: white;
    -fx-border-width: 2;
    -fx-border-radius: 20;
    -fx-text-fill: white;
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI Semibold", sans-serif;
    -fx-font-weight: bold;
    -fx-letter-spacing: 2;
    -fx-cursor: hand;
}

.lol-button-panel:hover {
