    -fx-background-color: #144733;
    -fx-padding: 20 15;
    -fx-min-width: 200;
}

.sidebar-logo {
    -fx-font-size: 24;
    -fx-font-weight: bold;
    -fx-text-fill: white;
}

.sidebar-item {
    -fx-background-color: transparent;
    -fx-text-fill: white;
    -fx-font-size: 14;
    -fx-alignment: CENTER_LEFT;
    -fx-padding: 10 15;
    -fx-background-radius: 5;
    -fx-cursor: hand;
    -fx-effect: null;
    -fx-transition: background-color 0.2s;
}

.sidebar-item:hover {
    -fx-background-color: #20694c;
    -fx-text-fill: #fff;
}

.sidebar-item:disabled {
    -fx-opacity: 0.4;
    -fx-cursor: default;
}

/* Search */
.search-input {
    -fx-background-color: white;
    -fx-background-radius: 20;
    -fx-border-color: #ced4da;
    -fx-border-radius: 20;
    -fx-padding: 8 15;
    -fx-font-size: 14;
}

.search-input:focused {
    -fx-border-color: #1F6F54;
}

/* Table */
.modern-table {
    -fx-background-color: white;
    -fx-border-color: #e0e0e0;
    -fx-border-radius: 5;
}

.modern-table .column-header {
    -fx-background-color: #f8f9fa;
    -fx-font-weight: bold;
    -fx-font-size: 13;
}

.modern-table .table-cell {
    -fx-padding: 10;
    -fx-font-size: 13;
}

/* Stat Cards */
.stat-card {
    -fx-background-color: white;
    -fx-background-radius: 10;
    -fx-padding: 15 25;
    -fx-spacing: 5;
    -fx-alignment: center;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.05), 5, 0.3, 0, 1);
}

.stat-card-mini {
    -fx-background-color: white;
    -fx-background-radius: 8;
    -fx-padding: 10 15;
    -fx-spacing: 3;
    -fx-alignment: center;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.05), 3, 0.2, 0, 1);
}

.stat-card-mini-admin {
    -fx-background-color: #1F6F54;
    -fx-background-radius: 8;
    -fx-padding: 10 15;
    -fx-spacing: 3;
    -fx-alignment: center;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.1), 5, 0.3, 0, 2);
}

.stat-label, .stat-label-mini {
    -fx-font-size: 12;
    -fx-text-fill: #666;
}

.stat-label-mini {
    -fx-font-size: 11;
}

.stat-value, .stat-value-mini {
    -fx-font-size: 24;
    -fx-font-weight: bold;
    -fx-text-fill: #1F6F54;
}

.stat-value-mini {
    -fx-font-size: 18;
}

/* Forms */
.form-label {
    -fx-font-size: 13;
    -fx-font-weight: bold;
    -fx-text-fill: #333;
}

.form-input {
    -fx-background-color: white;
    -fx-background-radius: 5;
    -fx-border-color: #ced4da;
    -fx-border-radius: 5;
    -fx-padding: 8 12;
    -fx-font-size: 14;
}

.form-input:focused {
    -fx-border-color: #1F6F54;
}

.form-combo {
    -fx-background-color: white;
    -fx-background-radius: 5;
    -fx-border-color: #ced4da;
    -fx-border-radius: 5;
    -fx-padding: 8 12;
    -fx-font-size: 14;
}

.error-label {
    -fx-font-size: 12;
    -fx-text-fill: #E74C3C;
}

/* ============================================
   MODERN ACCUEIL PAGE - NEW DESIGN
   ============================================ */

/* Main Container */
.main-container {
    -fx-background-color: transparent;
    -fx-padding: 0;
}

/* Floating Pill Navbar */
.navbar-pill {
    -fx-background-color: white;
    -fx-background-radius: 40;
    -fx-padding: 15 30;
    -fx-spacing: 20;
    -fx-alignment: CENTER_LEFT;
    -fx-min-height: 70;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.1), 20, 0.5, 0, 5);
}

/* Logo Text */
.logo-text {
    -fx-font-size: 26;
    -fx-font-weight: bold;
    -fx-text-fill: #1f6f5c;
    -fx-font-family: "Segoe UI", sans-serif;
}

/* Menu Container */
.menu-container {
    -fx-spacing: 25;
    -fx-alignment: CENTER;
}

/* Menu Items */
.menu-item {
    -fx-background-color: transparent;
    -fx-text-fill: #4a5568;
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI", sans-serif;
    -fx-padding: 10 15;
    -fx-cursor: hand;
    -fx-background-radius: 5;
}

.menu-item:hover {
    -fx-text-fill: #1f6f5c;
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
    -fx-background-color: rgba(31, 111, 92, 0.08);
}

/* Icon Container */
.icon-container {
    -fx-spacing: 10;
    -fx-alignment: CENTER;
}

/* Icon Button (Circle) */
.icon-button {
    -fx-background-color: #1f6f5c;
    -fx-text-fill: white;
    -fx-font-size: 16;
    -fx-min-width: 40;
    -fx-min-height: 40;
    -fx-max-width: 40;
    -fx-max-height: 40;
    -fx-padding: 0;
    -fx-cursor: hand;
    -fx-background-radius: 20;
}

.icon-button:hover {
    -fx-background-color: #2ecc71;
    -fx-scale-x: 1.1;
    -fx-scale-y: 1.1;
}

/* Profile Dropdown (Facebook Style) */
.profile-dropdown {
    -fx-background-color: white;
    -fx-background-radius: 12;
    -fx-padding: 8 0;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.15), 15, 0.5, 0, 5);
    -fx-min-width: 160;
    -fx-alignment: CENTER_LEFT;
    -fx-translate-x: 60;
}

/* Dropdown Item */
.dropdown-item {
    -fx-background-color: transparent;
    -fx-text-fill: #1f6f5c;
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI", sans-serif;
    -fx-padding: 12 20;
    -fx-cursor: hand;
    -fx-background-radius: 0;
    -fx-max-width: Infinity;
    -fx-alignment: CENTER_LEFT;
}

.dropdown-item:hover {
    -fx-background-color: #f0f9f6;
    -fx-text-fill: #2ecc71;
}

/* ============================================
   MODERN ACCUEIL - CARDS SECTION
   ============================================ */

/* Main Content Area */
.main-content {
    -fx-background-color: transparent;
}

/* Cards Section */
.cards-section {
    -fx-padding: 40;
    -fx-spacing: 30;
}

/* Card Container */
.card {
    -fx-background-color: white;
    -fx-background-radius: 20;
    -fx-padding: 25;
    -fx-spacing: 15;
    -fx-pref-width: 300;
    -fx-pref-height: 220;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.08), 15, 0.4, 0, 4);
    -fx-cursor: hand;
}

/* Card Hover Effect */
.card:hover {
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.15), 20, 0.5, 0, 8);
}

/* Card Icon Container */
.card-icon-container {
    -fx-background-color: #e8f5e9;
    -fx-background-radius: 50%;
