    -fx-text-fill: #1a1a1a;
    -fx-font-family: "Segoe UI", sans-serif;
}

/* Card Description */
.card-description {
    -fx-font-size: 14;
    -fx-text-fill: #666;
    -fx-font-family: "Segoe UI", sans-serif;
